#pragma once
#include "lvgl.h"
#include <stdbool.h>
#include <stdint.h>

// Creates a die with accurate polygonal faces, no floating die-type text.
// An excluded ADV/DIS die retains a small OUT marker, separate from its value.
lv_obj_t *dice_visual_create(lv_obj_t *tray, uint8_t sides, uint16_t face,
                             int size, bool discarded, bool percentile_tens);

// Hide the committed face while tossing; reveal it when the die settles.
// The numeric face is never regenerated by this presentation helper.
void dice_visual_set_rolling(lv_obj_t *die, bool rolling);

// Keep face-label sizing aligned with the die after rotation/reflow.
void dice_visual_resize(lv_obj_t *die, int size);
